static int rtl_nway_restart(struct r8152 *tp)
{
	int r;

	/* if autoneg is off, it's an error */
	r = r8152_mdio_read(tp, MII_BMCR);
	if (r < 0)
		goto out;

	if (r & BMCR_ANENABLE)
		r = r8152_mdio_write(tp, MII_BMCR, r | BMCR_ANRESTART);

out:
	if (r < 0)
		return r;
	else
		return 0;
}
